"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Textarea } from "@/components/ui/textarea"
import {
  AddIcon,
  CollectDigitsToolIcon,
  EndCallToolIcon,
  FindIcon,
  HttpRequestToolIcon,
  IvrToolIcon,
  RemoveIcon,
  SallaToolIcon,
  SwitchLanguageToolIcon,
  TransferToolIcon,
  VoicemailToolIcon,
  ZohoTicketToolIcon,
} from "@/components/mockups/scenario-single-screen/icons"
import { SheetSection } from "@/components/mockups/scenario-single-screen/setting-sheet"
import {
  type Destination,
  type ExtractionField,
  type KnowledgeBase,
  LANGUAGE_LABELS,
  type LanguageCode,
  type PerLanguage,
  PERSONAS,
  type SuccessCriterion,
  type TemplateVariable,
  type Tool,
  type ToolSlug,
} from "@/lib/mockups/scenario-single-screen-data"

const TIMEZONES = [
  "Asia/Riyadh",
  "Asia/Dubai",
  "Asia/Karachi",
  "Africa/Cairo",
  "Europe/London",
]

const TOOL_ICONS: Record<ToolSlug, React.ComponentType> = {
  "code-switching": SwitchLanguageToolIcon,
  "collect-digits": CollectDigitsToolIcon,
  "custom-api": HttpRequestToolIcon,
  "end-call": EndCallToolIcon,
  "ivr-navigation": IvrToolIcon,
  "salla-tools": SallaToolIcon,
  "transfer-to-human": TransferToolIcon,
  "voicemail-detection": VoicemailToolIcon,
  "zoho-desk-create-ticket": ZohoTicketToolIcon,
}

/* --------------------------------------------------------------- persona -- */

/**
 * A persona per language, because that is how the scenario stores it — one
 * voice cannot speak all three. Listing every configured language at once is
 * what stops this reading as a single "voice" dropdown that silently belongs
 * to whichever language you last had selected.
 */
export function PersonaDrawerBody({
  onPersonaChange,
  perLanguage,
}: {
  onPersonaChange: (language: LanguageCode, persona: string) => void
  perLanguage: PerLanguage[]
}) {
  return (
    <FieldGroup>
      {perLanguage.map((entry) => (
        <Field key={entry.language}>
          <FieldLabel htmlFor={`persona-${entry.language}`}>
            {LANGUAGE_LABELS[entry.language]}
          </FieldLabel>
          <Select
            onValueChange={(persona) => {
              onPersonaChange(entry.language, persona)
            }}
            value={entry.persona}
          >
            <SelectTrigger id={`persona-${entry.language}`}>
              <SelectValue placeholder="Select a persona" />
            </SelectTrigger>
            <SelectContent>
              {PERSONAS.map((persona) => (
                <SelectItem key={persona} value={persona}>
                  {persona}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <FieldDescription>
            Speaks the {LANGUAGE_LABELS[entry.language]} prompt and first
            message.
          </FieldDescription>
        </Field>
      ))}
    </FieldGroup>
  )
}

/* ------------------------------------------------------------- languages -- */

export function LanguagesDrawerBody({
  defaultLanguage,
  onDefaultChange,
  onTimezoneChange,
  perLanguage,
  timezone,
}: {
  defaultLanguage: LanguageCode
  onDefaultChange: (language: LanguageCode) => void
  onTimezoneChange: (timezone: string) => void
  perLanguage: PerLanguage[]
  timezone: string
}) {
  return (
    <>
      <SheetSection
        description="The default is the language a call opens in when the caller's is unknown."
        title="Configured languages"
      >
        <RadioGroup
          onValueChange={(value) => {
            onDefaultChange(value as LanguageCode)
          }}
          value={defaultLanguage}
        >
          <ItemGroup className="gap-2">
            {perLanguage.map((entry) => (
              <Item key={entry.language} size="sm" variant="outline">
                <ItemMedia>
                  <RadioGroupItem
                    id={`default-${entry.language}`}
                    value={entry.language}
                  />
                </ItemMedia>
                <ItemContent>
                  <ItemTitle>
                    <Label htmlFor={`default-${entry.language}`}>
                      {LANGUAGE_LABELS[entry.language]}
                    </Label>
                  </ItemTitle>
                </ItemContent>
                <ItemActions>
                  {entry.language === defaultLanguage ? (
                    <Badge variant="secondary">Default</Badge>
                  ) : (
                    <Button
                      aria-label={`Remove ${LANGUAGE_LABELS[entry.language]}`}
                      size="icon-sm"
                      variant="ghost"
                    >
                      <RemoveIcon />
                    </Button>
                  )}
                </ItemActions>
              </Item>
            ))}
          </ItemGroup>
        </RadioGroup>
        <Button size="sm" variant="outline">
          <AddIcon />
          Add a language
        </Button>
      </SheetSection>

      <SheetSection
        description="Dates and times the caller gives are read against this zone."
        title="Timezone"
      >
        <Select onValueChange={onTimezoneChange} value={timezone}>
          <SelectTrigger aria-label="Timezone">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {TIMEZONES.map((zone) => (
              <SelectItem key={zone} value={zone}>
                {zone}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </SheetSection>
    </>
  )
}

/* --------------------------------------------------------------- knowledge -- */

/**
 * Language coverage sits on every row, attached or not. A base with no content
 * in a language the scenario speaks is the failure this screen has to make
 * visible before it is attached, not after a call goes wrong.
 */
export function KnowledgeDrawerBody({
  bases,
  onToggle,
  spokenLanguages,
}: {
  bases: KnowledgeBase[]
  onToggle: (name: string) => void
  spokenLanguages: LanguageCode[]
}) {
  const [query, setQuery] = React.useState("")

  const matches = bases.filter((base) =>
    base.name.toLowerCase().includes(query.toLowerCase()),
  )

  return (
    <>
      <InputGroup>
        <InputGroupAddon>
          <FindIcon />
        </InputGroupAddon>
        <InputGroupInput
          aria-label="Search knowledge bases"
          onChange={(event) => {
            setQuery(event.target.value)
          }}
          placeholder="Search knowledge bases…"
          value={query}
        />
      </InputGroup>

      <ItemGroup className="gap-2">
        {matches.map((base) => {
          const gaps = spokenLanguages.filter(
            (language) => !base.languages.includes(language),
          )

          return (
            <Item key={base.name} size="sm" variant="outline">
              <ItemMedia>
                <Checkbox
                  checked={base.attached}
                  id={`kb-${base.name}`}
                  onCheckedChange={() => {
                    onToggle(base.name)
                  }}
                />
              </ItemMedia>
              <ItemContent>
                <ItemTitle>
                  <Label htmlFor={`kb-${base.name}`}>{base.name}</Label>
                </ItemTitle>
                <ItemDescription>
                  {base.documents} documents ·{" "}
                  {base.languages
                    .map((language) => LANGUAGE_LABELS[language])
                    .join(", ")}
                </ItemDescription>
              </ItemContent>
              {gaps.length > 0 && base.attached ? (
                <ItemActions>
                  <Badge variant="destructive">
                    No{" "}
                    {gaps
                      .map((language) => LANGUAGE_LABELS[language])
                      .join(", ")}
                  </Badge>
                </ItemActions>
              ) : null}
            </Item>
          )
        })}
      </ItemGroup>
    </>
  )
}

/* ------------------------------------------------------------------- tools -- */

/**
 * A tool's own configuration only appears once it is on. Nine tools each
 * showing their settings is the density that made the Configuration tab
 * unreadable; the switch is the disclosure.
 */
export function ToolsDrawerBody({
  onToggle,
  tools,
}: {
  onToggle: (slug: ToolSlug) => void
  tools: Tool[]
}) {
  return (
    <FieldGroup>
      {tools.map((tool) => {
        const Icon = TOOL_ICONS[tool.slug]

        return (
          <Field key={tool.slug} orientation="horizontal">
            <ItemMedia variant="icon">
              <Icon />
            </ItemMedia>
            <FieldContent>
              <FieldTitle>{tool.label}</FieldTitle>
              <FieldDescription>{tool.description}</FieldDescription>
              {tool.enabled && tool.summary ? (
                <div className="mt-2 flex items-center justify-between gap-3 rounded-lg bg-muted p-3">
                  <p className="text-sm text-muted-foreground">
                    {tool.summary}
                  </p>
                  <Button size="xs" variant="outline">
                    Edit
                  </Button>
                </div>
              ) : null}
            </FieldContent>
            <Switch
              aria-label={tool.label}
              checked={tool.enabled}
              onCheckedChange={() => {
                onToggle(tool.slug)
              }}
            />
          </Field>
        )
      })}
    </FieldGroup>
  )
}

/* -------------------------------------------------------- success criteria -- */

export function CriteriaDrawerBody({
  criteria,
  onCriteriaChange,
}: {
  criteria: SuccessCriterion[]
  onCriteriaChange: (criteria: SuccessCriterion[]) => void
}) {
  return (
    <>
      <FieldGroup>
        {criteria.map((criterion, index) => (
          <Field key={index}>
            <div className="flex items-center justify-between gap-2">
              <FieldLabel htmlFor={`criterion-${index}`}>
                Criterion {index + 1}
                {criterion.primary ? (
                  <Badge variant="secondary">Primary</Badge>
                ) : null}
              </FieldLabel>
              <Button
                aria-label={`Remove criterion ${index + 1}`}
                onClick={() => {
                  onCriteriaChange(criteria.filter((_, i) => i !== index))
                }}
                size="icon-sm"
                variant="ghost"
              >
                <RemoveIcon />
              </Button>
            </div>
            <Textarea
              id={`criterion-${index}`}
              onChange={(event) => {
                onCriteriaChange(
                  criteria.map((item, i) =>
                    i === index ? { ...item, text: event.target.value } : item,
                  ),
                )
              }}
              rows={3}
              value={criterion.text}
            />
          </Field>
        ))}
      </FieldGroup>

      <Button
        onClick={() => {
          onCriteriaChange([...criteria, { primary: false, text: "" }])
        }}
        size="sm"
        variant="outline"
      >
        <AddIcon />
        Add a criterion
      </Button>
    </>
  )
}

/* ------------------------------------------------------ template variables -- */

export function VariablesDrawerBody({
  onVariablesChange,
  variables,
}: {
  onVariablesChange: (variables: TemplateVariable[]) => void
  variables: TemplateVariable[]
}) {
  return (
    <>
      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Variable</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Default</TableHead>
              <TableHead>Used in</TableHead>
              <TableHead className="text-end">Required</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {variables.map((variable, index) => (
              <TableRow key={variable.name}>
                <TableCell className="font-mono">{variable.name}</TableCell>
                <TableCell className="text-muted-foreground">
                  {variable.type}
                </TableCell>
                <TableCell>
                  <Input
                    aria-label={`Default value for ${variable.name}`}
                    onChange={(event) => {
                      onVariablesChange(
                        variables.map((item, i) =>
                          i === index
                            ? { ...item, defaultValue: event.target.value }
                            : item,
                        ),
                      )
                    }}
                    placeholder="—"
                    value={variable.defaultValue}
                  />
                </TableCell>
                <TableCell className="text-muted-foreground">
                  {variable.usedIn
                    .map((language) => language.toUpperCase())
                    .join(", ")}
                </TableCell>
                <TableCell className="text-end">
                  <Checkbox
                    aria-label={`${variable.name} is required`}
                    checked={variable.required}
                    onCheckedChange={() => {
                      onVariablesChange(
                        variables.map((item, i) =>
                          i === index
                            ? { ...item, required: !item.required }
                            : item,
                        ),
                      )
                    }}
                  />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <Button size="sm" variant="outline">
        <AddIcon />
        Add a variable
      </Button>
    </>
  )
}

/* -------------------------------------------------------- data extraction -- */

export function ExtractionDrawerBody({
  destinations,
  enabled,
  fields,
  onDestinationToggle,
  onEnabledChange,
}: {
  destinations: Destination[]
  enabled: boolean
  fields: ExtractionField[]
  onDestinationToggle: (type: Destination["type"]) => void
  onEnabledChange: (enabled: boolean) => void
}) {
  return (
    <>
      <Field orientation="horizontal">
        <FieldContent>
          <FieldTitle>Extract data from every call</FieldTitle>
          <FieldDescription>
            Fields below are read out of the transcript when the call ends.
          </FieldDescription>
        </FieldContent>
        <Switch
          aria-label="Extract data from every call"
          checked={enabled}
          onCheckedChange={onEnabledChange}
        />
      </Field>

      <SheetSection title="Fields">
        <ItemGroup className="gap-2">
          {fields.map((field) => (
            <Item key={field.name} size="sm" variant="outline">
              <ItemContent>
                <ItemTitle className="font-mono">{field.name}</ItemTitle>
                <ItemDescription>{field.description}</ItemDescription>
              </ItemContent>
              <ItemActions>
                <Badge variant="outline">{field.type}</Badge>
                {field.required ? (
                  <Badge variant="secondary">Required</Badge>
                ) : null}
              </ItemActions>
            </Item>
          ))}
        </ItemGroup>
        <Button size="sm" variant="outline">
          <AddIcon />
          Add a field
        </Button>
      </SheetSection>

      <SheetSection
        description="Where the extracted fields are written once the call ends."
        title="Destinations"
      >
        <FieldGroup>
          {destinations.map((destination) => (
            <Field key={destination.type} orientation="horizontal">
              <FieldContent>
                <FieldTitle>
                  {destination.label}
                  {destination.connected ? null : (
                    <Badge variant="outline">Not connected</Badge>
                  )}
                </FieldTitle>
                <FieldDescription>{destination.description}</FieldDescription>
              </FieldContent>
              {destination.connected ? (
                <Switch
                  aria-label={destination.label}
                  checked={destination.enabled}
                  onCheckedChange={() => {
                    onDestinationToggle(destination.type)
                  }}
                />
              ) : (
                <Button size="sm" variant="outline">
                  Connect
                </Button>
              )}
            </Field>
          ))}
        </FieldGroup>
      </SheetSection>
    </>
  )
}

/* --------------------------------------------------- call recording delivery -- */

export function RecordingDrawerBody({
  onZohoChange,
  zohoCallActivity,
}: {
  onZohoChange: (enabled: boolean) => void
  zohoCallActivity: boolean
}) {
  return (
    <Field orientation="horizontal">
      <FieldContent>
        <FieldTitle>Zoho call activity</FieldTitle>
        <FieldDescription>
          Attach the recording to the matching Zoho CRM call activity when the
          call ends.
        </FieldDescription>
      </FieldContent>
      <Switch
        aria-label="Zoho call activity"
        checked={zohoCallActivity}
        onCheckedChange={onZohoChange}
      />
    </Field>
  )
}

import {
  Alert02Icon,
  ArrowRight01Icon,
  Building01Icon,
  Cancel01Icon,
  ChartLineData01Icon,
  CheckmarkCircle02Icon,
  DatabaseIcon,
  Delete02Icon,
  DialpadCircle01Icon,
  Globe02Icon,
  Idea01Icon,
  LanguageSkillIcon,
  Mic01Icon,
  PlayIcon,
  PlugSocketIcon,
  PlusSignIcon,
  RocketIcon,
  Route01Icon,
  Search01Icon,
  ShoppingBag01Icon,
  Target02Icon,
  TicketStarIcon,
  Timer01Icon,
  UserGroupIcon,
  VariableIcon,
  VoiceIcon,
  Wrench01Icon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* --- the rail: one glyph per setting, named for the setting ------------- */

/** Which persona speaks this scenario, per language. */
export const PersonaIcon = icon(Mic01Icon, "PersonaIcon")

/** The languages the scenario is configured in. */
export const LanguagesIcon = icon(Globe02Icon, "LanguagesIcon")

/** The timezone the agent reads dates and times against. */
export const TimezoneIcon = icon(Timer01Icon, "TimezoneIcon")

/** Bases the agent can look answers up in. */
export const KnowledgeIcon = icon(DatabaseIcon, "KnowledgeIcon")

/** Actions the agent can take mid-call. */
export const ToolsIcon = icon(Wrench01Icon, "ToolsIcon")

/** What counts as a successful call. */
export const CriteriaIcon = icon(Target02Icon, "CriteriaIcon")

/** Fields pulled out of the conversation when it ends. */
export const ExtractionIcon = icon(PlugSocketIcon, "ExtractionIcon")

/** Where the call recording is delivered. */
export const RecordingIcon = icon(VoiceIcon, "RecordingIcon")

/** Placeholders the prompt fills in at call time. */
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")

/** What the calls are telling you about this scenario. */
export const InsightsIcon = icon(Idea01Icon, "InsightsIcon")

/** Savings and cleanups only Sarj staff can act on. */
export const OpportunitiesIcon = icon(ChartLineData01Icon, "OpportunitiesIcon")

/** Moving the scenario to another organization. */
export const OwnershipIcon = icon(Building01Icon, "OwnershipIcon")

/* --- affordances -------------------------------------------------------- */

/** A rail row opens its drawer. */
export const OpenSettingIcon = icon(ArrowRight01Icon, "OpenSettingIcon")

/** Try the scenario before publishing it. */
export const TestCallIcon = icon(PlayIcon, "TestCallIcon")

/** Push the saved scenario live. */
export const PublishIcon = icon(RocketIcon, "PublishIcon")

/** Add a criterion, a variable, a language. */
export const AddIcon = icon(PlusSignIcon, "AddIcon")

/** Remove a row from a list inside a drawer. */
export const RemoveIcon = icon(Delete02Icon, "RemoveIcon")

/** Dismiss an insight without acting on it. */
export const DismissIcon = icon(Cancel01Icon, "DismissIcon")

/** Filter a long list down inside a drawer. */
export const FindIcon = icon(Search01Icon, "FindIcon")

/** Unsaved changes are waiting in the save bar. */
export const UnsavedIcon = icon(Alert02Icon, "UnsavedIcon")

/** A setting that is complete and needs nothing. */
export const ConfiguredIcon = icon(CheckmarkCircle02Icon, "ConfiguredIcon")

/* --- tools, each drawn as what it does on a call ------------------------ */

export const EndCallToolIcon = icon(Cancel01Icon, "EndCallToolIcon")
export const TransferToolIcon = icon(UserGroupIcon, "TransferToolIcon")
export const SwitchLanguageToolIcon = icon(
  LanguageSkillIcon,
  "SwitchLanguageToolIcon",
)
export const VoicemailToolIcon = icon(VoiceIcon, "VoicemailToolIcon")
export const CollectDigitsToolIcon = icon(
  DialpadCircle01Icon,
  "CollectDigitsToolIcon",
)
export const HttpRequestToolIcon = icon(PlugSocketIcon, "HttpRequestToolIcon")
export const IvrToolIcon = icon(Route01Icon, "IvrToolIcon")
export const SallaToolIcon = icon(ShoppingBag01Icon, "SallaToolIcon")
export const ZohoTicketToolIcon = icon(TicketStarIcon, "ZohoTicketToolIcon")

"use client"

import * as React from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  ConfiguredIcon,
  DismissIcon,
  UnsavedIcon,
} from "@/components/mockups/scenario-single-screen/icons"
import { SheetSection } from "@/components/mockups/scenario-single-screen/setting-sheet"
import {
  CURRENT_ORGANIZATION,
  type Insight,
  type InsightTarget,
  type Opportunity,
  ORGANIZATIONS,
} from "@/lib/mockups/scenario-single-screen-data"

/** What each insight's "take me there" button opens. */
const TARGET_LABELS: Record<InsightTarget, string> = {
  criteria: "success criteria",
  extraction: "data extraction",
  knowledge: "knowledge bases",
  prompt: "the prompt",
  tools: "tools",
}

/* -------------------------------------------------------------- insights -- */

/**
 * Every insight names the setting it is about and opens it.
 *
 * This is the one place the tabbed editor was actively hostile: an insight
 * would tell you the late-arrival policy was wrong and then leave you to work
 * out that the fix lived under a different tab. With one screen the insight
 * can just open the drawer.
 */
export function InsightsDrawerBody({
  dismissed,
  insights,
  onDismiss,
  onOpenTarget,
}: {
  dismissed: string[]
  insights: Insight[]
  onDismiss: (title: string) => void
  onOpenTarget: (target: InsightTarget) => void
}) {
  const open = insights.filter((insight) => !dismissed.includes(insight.title))

  if (open.length === 0) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <ConfiguredIcon />
          </EmptyMedia>
          <EmptyTitle>Nothing left to review</EmptyTitle>
          <EmptyDescription>
            New insights appear as calls come in.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    )
  }

  return (
    <div className="flex flex-col gap-3">
      {open.map((insight) => (
        <Card key={insight.title} size="sm">
          <CardContent className="flex flex-col gap-3">
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium">{insight.title}</p>
              <p className="text-sm text-muted-foreground">{insight.body}</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <Badge variant="secondary">{insight.calls} calls</Badge>
              <div className="flex-1" />
              <Button
                onClick={() => {
                  onDismiss(insight.title)
                }}
                size="xs"
                variant="ghost"
              >
                <DismissIcon />
                Dismiss
              </Button>
              <Button
                onClick={() => {
                  onOpenTarget(insight.target)
                }}
                size="xs"
                variant="outline"
              >
                Open {TARGET_LABELS[insight.target]}
              </Button>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

/* ------------------------------------------------- optimization opportunities -- */

const IMPACT_VARIANT = {
  high: "default",
  low: "outline",
  medium: "secondary",
} as const

export function OpportunitiesDrawerBody({
  opportunities,
}: {
  opportunities: Opportunity[]
}) {
  return (
    <div className="flex flex-col gap-3">
      {opportunities.map((opportunity) => (
        <Card key={opportunity.title} size="sm">
          <CardContent className="flex flex-col gap-3">
            <div className="flex items-start justify-between gap-3">
              <p className="text-sm font-medium">{opportunity.title}</p>
              <Badge variant={IMPACT_VARIANT[opportunity.impact]}>
                {opportunity.impact} impact
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">
              {opportunity.detail}
            </p>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

/* ------------------------------------------------------------- ownership -- */

export function OwnershipDrawerBody({
  attachedBases,
}: {
  attachedBases: number
}) {
  const [organization, setOrganization] = React.useState(CURRENT_ORGANIZATION)
  const moving = organization !== CURRENT_ORGANIZATION

  return (
    <SheetSection title="Owning organization">
      <Field>
        <FieldLabel htmlFor="owner-organization">Organization</FieldLabel>
        <Select onValueChange={setOrganization} value={organization}>
          <SelectTrigger id="owner-organization">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ORGANIZATIONS.map((name) => (
              <SelectItem key={name} value={name}>
                {name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <FieldDescription>
          Currently owned by {CURRENT_ORGANIZATION}.
        </FieldDescription>
      </Field>

      {moving ? (
        <Alert variant="destructive">
          <UnsavedIcon />
          <AlertTitle>
            {attachedBases} knowledge bases will be detached
          </AlertTitle>
          <AlertDescription>
            Knowledge bases do not move between organizations. Reattach the
            equivalents in {organization} before the next publish.
          </AlertDescription>
        </Alert>
      ) : null}

      <Button disabled={!moving} variant="destructive">
        Transfer to {organization}
      </Button>
    </SheetSection>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Separator } from "@/components/ui/separator"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  CriteriaDrawerBody,
  ExtractionDrawerBody,
  KnowledgeDrawerBody,
  LanguagesDrawerBody,
  PersonaDrawerBody,
  RecordingDrawerBody,
  ToolsDrawerBody,
  VariablesDrawerBody,
} from "@/components/mockups/scenario-single-screen/config-drawers"
import {
  CriteriaIcon,
  ExtractionIcon,
  InsightsIcon,
  KnowledgeIcon,
  LanguagesIcon,
  OpportunitiesIcon,
  OwnershipIcon,
  PersonaIcon,
  PublishIcon,
  RecordingIcon,
  TestCallIcon,
  TimezoneIcon,
  ToolsIcon,
  UnsavedIcon,
  VariablesIcon,
} from "@/components/mockups/scenario-single-screen/icons"
import {
  InsightsDrawerBody,
  OpportunitiesDrawerBody,
  OwnershipDrawerBody,
} from "@/components/mockups/scenario-single-screen/review-drawers"
import {
  RailGroup,
  SettingRow,
} from "@/components/mockups/scenario-single-screen/setting-rail"
import { SettingSheet } from "@/components/mockups/scenario-single-screen/setting-sheet"
import {
  DATA_EXTRACTION,
  DEFAULT_LANGUAGE,
  DESTINATIONS,
  type Destination,
  INSIGHTS,
  type InsightTarget,
  KNOWLEDGE_BASES,
  LANGUAGE_LABELS,
  LANGUAGE_SHORT,
  type LanguageCode,
  OPPORTUNITIES,
  PER_LANGUAGE,
  RECORD_SINKS,
  SCENARIO,
  SUCCESS_CRITERIA,
  TEMPLATE_VARIABLES,
  TIMEZONE,
  TOOLS,
  type ToolSlug,
  UNRESOLVED_INSIGHTS,
} from "@/lib/mockups/scenario-single-screen-data"

/** Every drawer this screen can open. One at a time, by design. */
type Setting =
  | "criteria"
  | "extraction"
  | "insights"
  | "knowledge"
  | "languages"
  | "opportunities"
  | "ownership"
  | "persona"
  | "recording"
  | "timezone"
  | "tools"
  | "variables"

/** Which drawer an insight's "open" button lands on. */
const INSIGHT_TARGETS: Record<InsightTarget, Setting | null> = {
  criteria: "criteria",
  extraction: "extraction",
  knowledge: "knowledge",
  /* The prompt is on the page, so there is nothing to open — closing the
     drawer already puts the reader in front of it. */
  prompt: null,
  tools: "tools",
}

export function ScenarioEditor({ isStaff }: { isStaff: boolean }) {
  const [openSetting, setOpenSetting] = React.useState<Setting | null>(null)
  const [dirty, setDirty] = React.useState(false)

  const [language, setLanguage] = React.useState<LanguageCode>(DEFAULT_LANGUAGE)
  const [defaultLanguage, setDefaultLanguage] =
    React.useState<LanguageCode>(DEFAULT_LANGUAGE)
  const [perLanguage, setPerLanguage] = React.useState(PER_LANGUAGE)
  const [timezone, setTimezone] = React.useState(TIMEZONE)
  const [bases, setBases] = React.useState(KNOWLEDGE_BASES)
  const [tools, setTools] = React.useState(TOOLS)
  const [criteria, setCriteria] = React.useState(SUCCESS_CRITERIA)
  const [variables, setVariables] = React.useState(TEMPLATE_VARIABLES)
  const [extractionOn, setExtractionOn] = React.useState(
    DATA_EXTRACTION.enabled,
  )
  const [destinations, setDestinations] = React.useState(DESTINATIONS)
  const [zohoRecording, setZohoRecording] = React.useState(
    RECORD_SINKS.zohoCallActivity,
  )
  const [dismissedInsights, setDismissedInsights] = React.useState<string[]>([])

  /** Every edit on this screen is the same kind of edit — one save bar. */
  const edit = <T,>(setter: (value: T) => void) => {
    return (value: T) => {
      setter(value)
      setDirty(true)
    }
  }

  const current =
    perLanguage.find((entry) => entry.language === language) ?? perLanguage[0]

  const updateCurrent = (patch: Partial<(typeof perLanguage)[number]>) => {
    setPerLanguage((entries) =>
      entries.map((entry) =>
        entry.language === language ? { ...entry, ...patch } : entry,
      ),
    )
    setDirty(true)
  }

  const spokenLanguages = perLanguage.map((entry) => entry.language)
  const attachedBases = bases.filter((base) => base.attached)
  const enabledTools = tools.filter((tool) => tool.enabled)
  const enabledDestinations = destinations.filter(
    (destination) => destination.enabled,
  )
  const openInsights = UNRESOLVED_INSIGHTS - dismissedInsights.length

  const reset = () => {
    setPerLanguage(PER_LANGUAGE)
    setDefaultLanguage(DEFAULT_LANGUAGE)
    setTimezone(TIMEZONE)
    setBases(KNOWLEDGE_BASES)
    setTools(TOOLS)
    setCriteria(SUCCESS_CRITERIA)
    setVariables(TEMPLATE_VARIABLES)
    setExtractionOn(DATA_EXTRACTION.enabled)
    setDestinations(DESTINATIONS)
    setZohoRecording(RECORD_SINKS.zohoCallActivity)
    setDirty(false)
  }

  return (
    <div className="flex flex-1 flex-col p-3 lg:p-4">
      <div className="mx-auto flex w-full max-w-350 flex-col gap-6">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-2xl font-semibold">{SCENARIO.name}</h1>
              <Badge className="bg-success/10 text-success">Active</Badge>
            </div>
            {/* The four numbers the header carried before, as one line. They
                are context for the editing below, not a dashboard. */}
            <p className="text-sm text-muted-foreground">
              {SCENARIO.calls.toLocaleString()} calls · {SCENARIO.successRate}%
              met success criteria · Created {SCENARIO.createdAt} · Published{" "}
              {SCENARIO.lastPublished}
            </p>
          </div>

          <div className="flex shrink-0 items-center gap-2">
            <Button
              onClick={() => {
                setOpenSetting("insights")
              }}
              variant="outline"
            >
              <InsightsIcon />
              Insights
              <Badge variant="secondary">{openInsights}</Badge>
            </Button>
            <Button variant="outline">
              <TestCallIcon />
              Test
            </Button>
            <Button>
              <PublishIcon />
              Publish
            </Button>
          </div>
        </header>

        <div className="flex flex-col gap-6 lg:flex-row lg:items-start">
          {/* What the agent says. The only thing on this screen a person
              writes rather than picks, so it gets the width. */}
          <div className="flex min-w-0 flex-1 flex-col gap-4">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p className="text-sm text-muted-foreground">
                Writing the {LANGUAGE_LABELS[current.language]} version
                {current.language === defaultLanguage ? " — the default" : ""}
              </p>
              <ToggleGroup
                onValueChange={(next) => {
                  if (next) setLanguage(next as LanguageCode)
                }}
                size="sm"
                type="single"
                value={language}
                variant="outline"
              >
                {perLanguage.map((entry) => (
                  <ToggleGroupItem
                    aria-label={LANGUAGE_LABELS[entry.language]}
                    key={entry.language}
                    value={entry.language}
                  >
                    {LANGUAGE_SHORT[entry.language]}
                  </ToggleGroupItem>
                ))}
              </ToggleGroup>
            </div>

            <Card>
              <CardHeader>
                <CardTitle>First message</CardTitle>
                <CardDescription>
                  What the agent opens the call with. Leave it off to let the
                  caller speak first.
                </CardDescription>
                <CardAction>
                  <Switch
                    aria-label="First message"
                    checked={current.firstMessageEnabled}
                    onCheckedChange={(checked) => {
                      updateCurrent({ firstMessageEnabled: checked })
                    }}
                  />
                </CardAction>
              </CardHeader>
              <CardContent>
                <Input
                  aria-label="First message"
                  dir={
                    current.language === "ar" || current.language === "ur"
                      ? "rtl"
                      : "ltr"
                  }
                  disabled={!current.firstMessageEnabled}
                  onChange={(event) => {
                    updateCurrent({ firstMessage: event.target.value })
                  }}
                  value={current.firstMessage}
                />
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Instruction prompt</CardTitle>
                <CardDescription>
                  How the agent behaves for the whole call.
                </CardDescription>
              </CardHeader>
              <CardContent className="flex flex-col gap-4">
                <Textarea
                  aria-label="Instruction prompt"
                  className="min-h-140 font-mono"
                  dir={
                    current.language === "ar" || current.language === "ur"
                      ? "rtl"
                      : "ltr"
                  }
                  onChange={(event) => {
                    updateCurrent({ prompt: event.target.value })
                  }}
                  value={current.prompt}
                />

                <Separator />

                {/* Variables belong under the prompt that spends them, not in
                    a table of their own further down the page. The chips are
                    the whole list; the drawer is where types and defaults
                    live. */}
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-sm text-muted-foreground">
                    Variables
                  </span>
                  {variables.map((variable) => (
                    <Badge
                      className="font-mono"
                      key={variable.name}
                      variant="outline"
                    >
                      {`{{${variable.name}}}`}
                    </Badge>
                  ))}
                  <Button
                    onClick={() => {
                      setOpenSetting("variables")
                    }}
                    size="xs"
                    variant="ghost"
                  >
                    Manage
                  </Button>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Everything the scenario is set to, readable without opening a
              thing. The rail is the replacement for the Configuration tab. */}
          <aside className="flex w-full shrink-0 flex-col gap-4 lg:sticky lg:top-4 lg:w-96">
            <RailGroup title="How it speaks">
              <SettingRow
                icon={PersonaIcon}
                onOpen={() => {
                  setOpenSetting("persona")
                }}
                title="Persona"
                value={current.persona}
              />
              <SettingRow
                icon={LanguagesIcon}
                onOpen={() => {
                  setOpenSetting("languages")
                }}
                title="Languages"
                value={`${spokenLanguages
                  .map((code) => LANGUAGE_LABELS[code])
                  .join(", ")} · ${LANGUAGE_LABELS[defaultLanguage]} default`}
              />
              <SettingRow
                icon={TimezoneIcon}
                onOpen={() => {
                  setOpenSetting("timezone")
                }}
                title="Timezone"
                value={timezone}
              />
            </RailGroup>

            <RailGroup title="What it knows and can do">
              <SettingRow
                icon={KnowledgeIcon}
                onOpen={() => {
                  setOpenSetting("knowledge")
                }}
                title="Knowledge bases"
                value={
                  attachedBases.length === 0
                    ? "None attached"
                    : attachedBases.map((base) => base.name).join(", ")
                }
              />
              <SettingRow
                icon={ToolsIcon}
                onOpen={() => {
                  setOpenSetting("tools")
                }}
                title="Tools"
                value={
                  enabledTools.length === 0
                    ? "None enabled"
                    : enabledTools.map((tool) => tool.label).join(", ")
                }
              />
              <SettingRow
                icon={VariablesIcon}
                onOpen={() => {
                  setOpenSetting("variables")
                }}
                title="Template variables"
                value={`${variables.length} · ${
                  variables.filter((variable) => variable.required).length
                } required`}
              />
            </RailGroup>

            <RailGroup title="When the call ends">
              <SettingRow
                icon={CriteriaIcon}
                onOpen={() => {
                  setOpenSetting("criteria")
                }}
                title="Success criteria"
                value={`${criteria.length} criteria · ${
                  criteria.filter((criterion) => criterion.primary).length
                } primary`}
              />
              <SettingRow
                icon={ExtractionIcon}
                onOpen={() => {
                  setOpenSetting("extraction")
                }}
                title="Data extraction"
                value={
                  extractionOn
                    ? `${DATA_EXTRACTION.fields.length} fields → ${
                        enabledDestinations.length === 0
                          ? "nowhere yet"
                          : enabledDestinations
                              .map((destination) => destination.label)
                              .join(", ")
                      }`
                    : "Off"
                }
              />
              <SettingRow
                icon={RecordingIcon}
                onOpen={() => {
                  setOpenSetting("recording")
                }}
                title="Recording delivery"
                value={zohoRecording ? "Zoho call activity" : "Not delivered"}
              />
            </RailGroup>

            {isStaff ? (
              <RailGroup title="Sarj staff">
                <SettingRow
                  icon={OpportunitiesIcon}
                  onOpen={() => {
                    setOpenSetting("opportunities")
                  }}
                  title="Optimization opportunities"
                  value={`${OPPORTUNITIES.length} open`}
                />
                <SettingRow
                  icon={OwnershipIcon}
                  onOpen={() => {
                    setOpenSetting("ownership")
                  }}
                  title="Owning organization"
                  value="Sizzler KSA"
                />
              </RailGroup>
            ) : null}
          </aside>
        </div>
      </div>

      {/* One save bar for the page and every drawer on it, so there is a
          single answer to "is this live yet". */}
      {dirty ? (
        <div className="sticky bottom-4 z-sticky mx-auto mt-6 w-full max-w-350">
          <Card>
            <CardContent className="flex flex-wrap items-center justify-between gap-4">
              <div className="flex items-center gap-2">
                <span className="text-warning">
                  <UnsavedIcon />
                </span>
                <p className="text-sm font-medium">You have unsaved changes</p>
              </div>
              <div className="flex items-center gap-2">
                <Button onClick={reset} variant="outline">
                  Clear
                </Button>
                <Button
                  onClick={() => {
                    setDirty(false)
                  }}
                >
                  Save
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      ) : null}

      {/* --- the drawers ------------------------------------------------- */}

      <SettingSheet
        description="One voice per language. The persona also carries the turn timing and backchannel settings that language uses."
        onOpenChange={(open) => {
          setOpenSetting(open ? "persona" : null)
        }}
        open={openSetting === "persona"}
        title="Persona"
      >
        <PersonaDrawerBody
          onPersonaChange={(code, persona) => {
            setPerLanguage((entries) =>
              entries.map((entry) =>
                entry.language === code ? { ...entry, persona } : entry,
              ),
            )
            setDirty(true)
          }}
          perLanguage={perLanguage}
        />
      </SettingSheet>

      <SettingSheet
        description="Each language keeps its own prompt, first message and persona."
        onOpenChange={(open) => {
          setOpenSetting(open ? "languages" : null)
        }}
        open={openSetting === "languages" || openSetting === "timezone"}
        title="Languages and timezone"
      >
        <LanguagesDrawerBody
          defaultLanguage={defaultLanguage}
          onDefaultChange={edit(setDefaultLanguage)}
          onTimezoneChange={edit(setTimezone)}
          perLanguage={perLanguage}
          timezone={timezone}
        />
      </SettingSheet>

      <SettingSheet
        description="Attached bases are searched when the agent needs a fact it was not told."
        onOpenChange={(open) => {
          setOpenSetting(open ? "knowledge" : null)
        }}
        open={openSetting === "knowledge"}
        title="Knowledge bases"
      >
        <KnowledgeDrawerBody
          bases={bases}
          onToggle={(name) => {
            setBases((entries) =>
              entries.map((base) =>
                base.name === name
                  ? { ...base, attached: !base.attached }
                  : base,
              ),
            )
            setDirty(true)
          }}
          spokenLanguages={spokenLanguages}
        />
      </SettingSheet>

      <SettingSheet
        description="Actions the agent can take during a call, beyond talking."
        onOpenChange={(open) => {
          setOpenSetting(open ? "tools" : null)
        }}
        open={openSetting === "tools"}
        title="Tools"
      >
        <ToolsDrawerBody
          onToggle={(slug: ToolSlug) => {
            setTools((entries) =>
              entries.map((tool) =>
                tool.slug === slug ? { ...tool, enabled: !tool.enabled } : tool,
              ),
            )
            setDirty(true)
          }}
          tools={tools}
        />
      </SettingSheet>

      <SettingSheet
        description="What a call has to achieve to be scored as successful."
        onOpenChange={(open) => {
          setOpenSetting(open ? "criteria" : null)
        }}
        open={openSetting === "criteria"}
        title="Success criteria"
      >
        <CriteriaDrawerBody
          criteria={criteria}
          onCriteriaChange={edit(setCriteria)}
        />
      </SettingSheet>

      <SettingSheet
        description="Placeholders the prompt and first message fill in when a call starts."
        onOpenChange={(open) => {
          setOpenSetting(open ? "variables" : null)
        }}
        open={openSetting === "variables"}
        title="Template variables"
      >
        <VariablesDrawerBody
          onVariablesChange={edit(setVariables)}
          variables={variables}
        />
      </SettingSheet>

      <SettingSheet
        description="Fields read out of the transcript when the call ends, and where they go."
        onOpenChange={(open) => {
          setOpenSetting(open ? "extraction" : null)
        }}
        open={openSetting === "extraction"}
        title="Data extraction"
      >
        <ExtractionDrawerBody
          destinations={destinations}
          enabled={extractionOn}
          fields={DATA_EXTRACTION.fields}
          onDestinationToggle={(type: Destination["type"]) => {
            setDestinations((entries) =>
              entries.map((destination) =>
                destination.type === type
                  ? { ...destination, enabled: !destination.enabled }
                  : destination,
              ),
            )
            setDirty(true)
          }}
          onEnabledChange={edit(setExtractionOn)}
        />
      </SettingSheet>

      <SettingSheet
        description="Where the call recording is sent once the call ends."
        onOpenChange={(open) => {
          setOpenSetting(open ? "recording" : null)
        }}
        open={openSetting === "recording"}
        title="Recording delivery"
      >
        <RecordingDrawerBody
          onZohoChange={edit(setZohoRecording)}
          zohoCallActivity={zohoRecording}
        />
      </SettingSheet>

      <SettingSheet
        description="What the last 90 days of calls say about this scenario."
        onOpenChange={(open) => {
          setOpenSetting(open ? "insights" : null)
        }}
        open={openSetting === "insights"}
        title="Insights"
      >
        <InsightsDrawerBody
          dismissed={dismissedInsights}
          insights={INSIGHTS}
          onDismiss={(title) => {
            setDismissedInsights((titles) => [...titles, title])
          }}
          onOpenTarget={(target) => {
            setOpenSetting(INSIGHT_TARGETS[target])
          }}
        />
      </SettingSheet>

      <SettingSheet
        description="Cost and quality wins Sarj staff can act on for this scenario."
        onOpenChange={(open) => {
          setOpenSetting(open ? "opportunities" : null)
        }}
        open={openSetting === "opportunities"}
        title="Optimization opportunities"
      >
        <OpportunitiesDrawerBody opportunities={OPPORTUNITIES} />
      </SettingSheet>

      <SettingSheet
        description="Move this scenario to another organization."
        onOpenChange={(open) => {
          setOpenSetting(open ? "ownership" : null)
        }}
        open={openSetting === "ownership"}
        title="Owning organization"
      >
        <OwnershipDrawerBody attachedBases={attachedBases.length} />
      </SettingSheet>
    </div>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Textarea } from "@/components/ui/textarea"
import {
  AddIcon,
  CollectDigitsToolIcon,
  EndCallToolIcon,
  FindIcon,
  HttpRequestToolIcon,
  IvrToolIcon,
  RemoveIcon,
  SallaToolIcon,
  SwitchLanguageToolIcon,
  TransferToolIcon,
  VoicemailToolIcon,
  ZohoTicketToolIcon,
} from "@/components/mockups/scenario-single-screen/v2/icons"
import { SheetSection } from "@/components/mockups/scenario-single-screen/v2/setting-sheet"
import {
  type Destination,
  type ExtractionField,
  type KnowledgeBase,
  LANGUAGE_LABELS,
  type LanguageCode,
  type PerLanguage,
  PERSONAS,
  type SuccessCriterion,
  type TemplateVariable,
  type Tool,
  type ToolSlug,
} from "@/lib/mockups/scenario-single-screen-data"

const TIMEZONES = [
  "Asia/Riyadh",
  "Asia/Dubai",
  "Asia/Karachi",
  "Africa/Cairo",
  "Europe/London",
]

const TOOL_ICONS: Record<ToolSlug, React.ComponentType> = {
  "code-switching": SwitchLanguageToolIcon,
  "collect-digits": CollectDigitsToolIcon,
  "custom-api": HttpRequestToolIcon,
  "end-call": EndCallToolIcon,
  "ivr-navigation": IvrToolIcon,
  "salla-tools": SallaToolIcon,
  "transfer-to-human": TransferToolIcon,
  "voicemail-detection": VoicemailToolIcon,
  "zoho-desk-create-ticket": ZohoTicketToolIcon,
}

/* --------------------------------------------------------------- persona -- */

/**
 * A persona per language, because that is how the scenario stores it — one
 * voice cannot speak all three. Listing every configured language at once is
 * what stops this reading as a single "voice" dropdown that silently belongs
 * to whichever language you last had selected.
 */
export function PersonaDrawerBody({
  onPersonaChange,
  perLanguage,
}: {
  onPersonaChange: (language: LanguageCode, persona: string) => void
  perLanguage: PerLanguage[]
}) {
  return (
    <FieldGroup>
      {perLanguage.map((entry) => (
        <Field key={entry.language}>
          <FieldLabel htmlFor={`persona-${entry.language}`}>
            {LANGUAGE_LABELS[entry.language]}
          </FieldLabel>
          <Select
            onValueChange={(persona) => {
              onPersonaChange(entry.language, persona)
            }}
            value={entry.persona}
          >
            <SelectTrigger id={`persona-${entry.language}`}>
              <SelectValue placeholder="Select a persona" />
            </SelectTrigger>
            <SelectContent>
              {PERSONAS.map((persona) => (
                <SelectItem key={persona} value={persona}>
                  {persona}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <FieldDescription>
            Speaks the {LANGUAGE_LABELS[entry.language]} prompt and first
            message.
          </FieldDescription>
        </Field>
      ))}
    </FieldGroup>
  )
}

/* ------------------------------------------------------------- languages -- */

export function LanguagesDrawerBody({
  defaultLanguage,
  onDefaultChange,
  onTimezoneChange,
  perLanguage,
  timezone,
}: {
  defaultLanguage: LanguageCode
  onDefaultChange: (language: LanguageCode) => void
  onTimezoneChange: (timezone: string) => void
  perLanguage: PerLanguage[]
  timezone: string
}) {
  return (
    <>
      <SheetSection
        description="The default is the language a call opens in when the caller's is unknown."
        title="Configured languages"
      >
        <RadioGroup
          onValueChange={(value) => {
            onDefaultChange(value as LanguageCode)
          }}
          value={defaultLanguage}
        >
          <ItemGroup className="gap-2">
            {perLanguage.map((entry) => (
              <Item key={entry.language} size="sm" variant="outline">
                <ItemMedia>
                  <RadioGroupItem
                    id={`default-${entry.language}`}
                    value={entry.language}
                  />
                </ItemMedia>
                <ItemContent>
                  <ItemTitle>
                    <Label htmlFor={`default-${entry.language}`}>
                      {LANGUAGE_LABELS[entry.language]}
                    </Label>
                  </ItemTitle>
                </ItemContent>
                <ItemActions>
                  {entry.language === defaultLanguage ? (
                    <Badge variant="secondary">Default</Badge>
                  ) : (
                    <Button
                      aria-label={`Remove ${LANGUAGE_LABELS[entry.language]}`}
                      size="icon-sm"
                      variant="ghost"
                    >
                      <RemoveIcon />
                    </Button>
                  )}
                </ItemActions>
              </Item>
            ))}
          </ItemGroup>
        </RadioGroup>
        <Button size="sm" variant="outline">
          <AddIcon />
          Add a language
        </Button>
      </SheetSection>

      <SheetSection
        description="Dates and times the caller gives are read against this zone."
        title="Timezone"
      >
        <Select onValueChange={onTimezoneChange} value={timezone}>
          <SelectTrigger aria-label="Timezone">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {TIMEZONES.map((zone) => (
              <SelectItem key={zone} value={zone}>
                {zone}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </SheetSection>
    </>
  )
