"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldSeparator,
  FieldTitle,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import {
  FLOW_META,
  SECTION_META,
  SECTION_TOTAL,
  filledCount,
  variableLabel,
  type SectionedPrompt,
} from "@/lib/mockups/scenario-single-screen-v2-data"
import { cn } from "@/lib/utils"

import {
  AddIcon,
  DragStepIcon,
  RawPromptIcon,
  RemoveIcon,
} from "@/components/mockups/scenario-single-screen/v2/icons"

/**
 * The instruction prompt, written as the six things it says.
 *
 * The review said the prompting area is not intuitive for a business user, and
 * the reason is that the prompt was never one thing: it is already an identity,
 * a refusal, a goal, a script, a tone and an escalation rule, glued together
 * with `#` headings. A person who has not written a prompt before cannot see
 * that, so they get a wall of monospace and no idea whether they have missed
 * anything.
 *
 * Each of those becomes a field with a plain label, one line saying what
 * belongs in it, and an example in the placeholder. The call script becomes a
 * numbered list, because it is the one part that is genuinely ordered and free
 * text hides that. Nothing is taken away — `Raw prompt` opens exactly what the
 * model is sent, and the markdown it shows is byte-identical to what v1 stores.
 */
export function PromptBuilder({
  onChange,
  onOpenRaw,
  onOpenVariables,
  prompt,
  rtl,
  variables,
}: {
  onChange: (prompt: SectionedPrompt) => void
  onOpenRaw: () => void
  onOpenVariables: () => void
  prompt: SectionedPrompt
  rtl: boolean
  /** Variable names the prompt may spend, already ordered for display. */
  variables: string[]
}) {
  const dir = rtl ? "rtl" : "ltr"
  const filled = filledCount(prompt)
  const complete = filled === SECTION_TOTAL

  const set = (patch: Partial<SectionedPrompt>) =>
    onChange({ ...prompt, ...patch })

  return (
    <Card>
      <CardHeader>
        <CardTitle>What the agent does</CardTitle>
        <CardDescription>
          Six things it needs to know, in your own words. It follows them for
          the whole call.
        </CardDescription>

        <CardAction className="flex items-center gap-2">
          {/* A business user's real question is "am I done?", and a blob of
              text cannot answer it. The count can. */}
          <Badge
            className={cn(
              "tabular-nums",
              complete && "bg-success-tint text-success-tint-foreground",
            )}
            variant="secondary"
          >
            {filled} of {SECTION_TOTAL} filled
          </Badge>

          {/* The escape hatch. Everything above is a view onto this, so the
              people who were happy writing markdown lose nothing. */}
          <Button onClick={onOpenRaw} size="sm" variant="outline">
            <RawPromptIcon />
            Raw prompt
          </Button>
        </CardAction>
      </CardHeader>

      <CardContent>
        <FieldGroup>
          {SECTION_META.map((meta) => (
            <React.Fragment key={meta.id}>
              <SectionField
                dir={dir}
                example={meta.example}
                help={meta.help}
                label={meta.label}
                onChange={(value) =>
                  set({ [meta.id]: value } as Partial<SectionedPrompt>)
                }
                onOpenVariables={onOpenVariables}
                value={prompt[meta.id]}
                variables={variables}
              />

              {/* The script sits after the goal, where it does in the prompt
                  the model is sent — the order on screen is the order it runs. */}
              {meta.id === "context" ? (
                <FlowField
                  dir={dir}
                  onChange={(flow) => set({ flow })}
                  steps={prompt.flow}
                />
              ) : null}
            </React.Fragment>
          ))}
        </FieldGroup>
      </CardContent>
    </Card>
  )
}

/**
 * One prose section.
 *
 * The variable chips appear only while this field has focus: six permanent
 * chip rows would be six copies of the same list, and the moment a person
 * needs them is the moment they are typing.
 */
function SectionField({
  dir,
  example,
  help,
  label,
  onChange,
  onOpenVariables,
  value,
  variables,
}: {
  dir: "ltr" | "rtl"
  example: string
  help: string
  label: string
  onChange: (value: string) => void
  onOpenVariables: () => void
  value: string
  variables: string[]
}) {
  const field = React.useRef<HTMLTextAreaElement>(null)
  const [focused, setFocused] = React.useState(false)

  function insert(name: string) {
    const element = field.current
    if (!element) return

    const token = `{{${name}}}`
    const start = element.selectionStart ?? value.length
    const end = element.selectionEnd ?? start
    onChange(value.slice(0, start) + token + value.slice(end))

    /* Put the caret after what was just inserted, so a second chip does not
       land inside the first. */
    requestAnimationFrame(() => {
      element.focus()
      element.setSelectionRange(start + token.length, start + token.length)
    })
  }

  return (
    <Field>
      <FieldTitle>{label}</FieldTitle>
      <FieldDescription>{help}</FieldDescription>

      <Textarea
        aria-label={label}
        className="min-h-20"
        dir={dir}
        onBlur={() => setFocused(false)}
        onChange={(event) => onChange(event.target.value)}
        onFocus={() => setFocused(true)}
        placeholder={`For example: ${example}`}
        ref={field}
        value={value}
      />

      {focused ? (
        <div className="flex flex-wrap items-center gap-1.5">
          <span className="text-xs text-muted-foreground">Insert</span>
          {variables.map((name) => (
            <Button
              key={name}
              /* Mouse-down would blur the textarea before the click lands,
                 taking the caret — and the chip row — with it. */
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => insert(name)}
              size="xs"
              type="button"
              variant="secondary"
            >
              {variableLabel(name)}
            </Button>
          ))}
          <Button
            onMouseDown={(event) => event.preventDefault()}
            onClick={onOpenVariables}
            size="xs"
            variant="ghost"
          >
            Manage
          </Button>
        </div>
      ) : null}
    </Field>
  )
}

/**
 * The call script, as ordered steps.
 *
 * Written as a paragraph the order is invisible, and order is the whole point
 * — the agent works down it. Numbering it makes that legible, and makes "move
 * the confirmation before the close" a drag rather than a rewrite.
 */
function FlowField({
  dir,
  onChange,
  steps,
}: {
  dir: "ltr" | "rtl"
  onChange: (steps: string[]) => void
  steps: string[]
}) {
  const [dragging, setDragging] = React.useState<number | null>(null)

  function move(from: number, to: number) {
    if (to < 0 || to >= steps.length) return
    const next = [...steps]
    const [moved] = next.splice(from, 1)
    next.splice(to, 0, moved)
    onChange(next)
  }

  return (
    <Field>
      <FieldTitle>{FLOW_META.label}</FieldTitle>
      <FieldDescription>{FLOW_META.help}</FieldDescription>

      <div className="flex flex-col gap-2">
        {steps.map((step, index) => (
          <div
            className={cn(
              "flex items-center gap-2",
              dragging === index && "opacity-60",
            )}
            draggable={dragging === index}
            key={index}
            onDragEnd={() => setDragging(null)}
            onDragEnter={() => {
              if (dragging !== null && dragging !== index) {
                move(dragging, index)
                setDragging(index)
              }
            }}
            onDragOver={(event) => event.preventDefault()}
          >
            {/* Arming the drag on the grip alone keeps the text selectable —
                a row that is always draggable cannot be edited with a mouse. */}
            <Button
              aria-label={`Reorder step ${index + 1}`}
              className="cursor-grab"
              onKeyDown={(event) => {
                if (event.key === "ArrowUp") {
                  event.preventDefault()
                  move(index, index - 1)
                }
                if (event.key === "ArrowDown") {
                  event.preventDefault()
                  move(index, index + 1)
                }
              }}
              onPointerDown={() => setDragging(index)}
              onPointerUp={() => setDragging(null)}
              size="icon-sm"
              variant="ghost"
            >
              <DragStepIcon />
            </Button>

            <Badge className="tabular-nums" variant="secondary">
              {index + 1}
            </Badge>

            <Input
              aria-label={`Step ${index + 1}`}
              dir={dir}
              onChange={(event) => {
                const next = [...steps]
                next[index] = event.target.value
                onChange(next)
              }}
              value={step}
            />

            <Button
              aria-label={`Remove step ${index + 1}`}
              onClick={() => onChange(steps.filter((_, at) => at !== index))}
              size="icon-sm"
              variant="ghost"
            >
              <RemoveIcon />
            </Button>
          </div>
        ))}

        <div>
          <Button
            onClick={() => onChange([...steps, ""])}
            size="sm"
            variant="outline"
          >
            <AddIcon />
            Add step
          </Button>
        </div>
      </div>

      {steps.length ? null : (
        <FieldDescription>
          No steps yet. The agent will improvise the order of the call.
        </FieldDescription>
      )}

      <FieldSeparator />
    </Field>
  )
}

"use client"

import * as React from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  ConfiguredIcon,
  DismissIcon,
  UnsavedIcon,
} from "@/components/mockups/scenario-single-screen/v2/icons"
import { SheetSection } from "@/components/mockups/scenario-single-screen/v2/setting-sheet"
import {
  CURRENT_ORGANIZATION,
  type Insight,
  type InsightTarget,
  type Opportunity,
  ORGANIZATIONS,
} from "@/lib/mockups/scenario-single-screen-data"

/** What each insight's "take me there" button opens. */
const TARGET_LABELS: Record<InsightTarget, string> = {
  criteria: "success criteria",
  extraction: "data extraction",
  knowledge: "knowledge bases",
  prompt: "the prompt",
  tools: "tools",
}

/* -------------------------------------------------------------- insights -- */

/**
 * Every insight names the setting it is about and opens it.
 *
 * This is the one place the tabbed editor was actively hostile: an insight
 * would tell you the late-arrival policy was wrong and then leave you to work
 * out that the fix lived under a different tab. With one screen the insight
 * can just open the drawer.
 */
export function InsightsDrawerBody({
  dismissed,
  insights,
  onDismiss,
  onOpenTarget,
}: {
  dismissed: string[]
  insights: Insight[]
  onDismiss: (title: string) => void
  onOpenTarget: (target: InsightTarget) => void
}) {
  const open = insights.filter((insight) => !dismissed.includes(insight.title))

  if (open.length === 0) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <ConfiguredIcon />
          </EmptyMedia>
          <EmptyTitle>Nothing left to review</EmptyTitle>
          <EmptyDescription>
            New insights appear as calls come in.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    )
  }

  return (
    <div className="flex flex-col gap-3">
      {open.map((insight) => (
        <Card key={insight.title} size="sm">
          <CardContent className="flex flex-col gap-3">
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium">{insight.title}</p>
              <p className="text-sm text-muted-foreground">{insight.body}</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <Badge variant="secondary">{insight.calls} calls</Badge>
              <div className="flex-1" />
              <Button
                onClick={() => {
                  onDismiss(insight.title)
                }}
                size="xs"
                variant="ghost"
              >
                <DismissIcon />
                Dismiss
              </Button>
              <Button
                onClick={() => {
                  onOpenTarget(insight.target)
                }}
                size="xs"
                variant="outline"
              >
                Open {TARGET_LABELS[insight.target]}
              </Button>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

/* ------------------------------------------------- optimization opportunities -- */

const IMPACT_VARIANT = {
  high: "default",
  low: "outline",
  medium: "secondary",
} as const

export function OpportunitiesDrawerBody({
  opportunities,
}: {
  opportunities: Opportunity[]
}) {
  return (
    <div className="flex flex-col gap-3">
      {opportunities.map((opportunity) => (
        <Card key={opportunity.title} size="sm">
          <CardContent className="flex flex-col gap-3">
            <div className="flex items-start justify-between gap-3">
              <p className="text-sm font-medium">{opportunity.title}</p>
              <Badge variant={IMPACT_VARIANT[opportunity.impact]}>
                {opportunity.impact} impact
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">
              {opportunity.detail}
            </p>
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

/* ------------------------------------------------------------- ownership -- */

export function OwnershipDrawerBody({
  attachedBases,
}: {
  attachedBases: number
}) {
  const [organization, setOrganization] = React.useState(CURRENT_ORGANIZATION)
  const moving = organization !== CURRENT_ORGANIZATION

  return (
    <SheetSection title="Owning organization">
      <Field>
        <FieldLabel htmlFor="owner-organization">Organization</FieldLabel>
        <Select onValueChange={setOrganization} value={organization}>
          <SelectTrigger id="owner-organization">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ORGANIZATIONS.map((name) => (
              <SelectItem key={name} value={name}>
                {name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <FieldDescription>
          Currently owned by {CURRENT_ORGANIZATION}.
        </FieldDescription>
      </Field>

      {moving ? (
        <Alert variant="destructive">
          <UnsavedIcon />
          <AlertTitle>
            {attachedBases} knowledge bases will be detached
          </AlertTitle>
          <AlertDescription>
            Knowledge bases do not move between organizations. Reattach the
            equivalents in {organization} before the next publish.
          </AlertDescription>
        </Alert>
      ) : null}

      <Button disabled={!moving} variant="destructive">
        Transfer to {organization}
      </Button>
    </SheetSection>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Switch } from "@/components/ui/switch"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  CriteriaDrawerBody,
  ExtractionDrawerBody,
  KnowledgeDrawerBody,
  LanguagesDrawerBody,
  PersonaDrawerBody,
  RecordingDrawerBody,
  ToolsDrawerBody,
  VariablesDrawerBody,
} from "@/components/mockups/scenario-single-screen/v2/config-drawers"
import {
  CriteriaIcon,
  ExtractionIcon,
  InsightsIcon,
  KnowledgeIcon,
  LanguagesIcon,
  OpportunitiesIcon,
  OwnershipIcon,
  PersonaIcon,
  PublishIcon,
  RecordingIcon,
  TestCallIcon,
  TimezoneIcon,
  ToolsIcon,
  UnsavedIcon,
  VariablesIcon,
} from "@/components/mockups/scenario-single-screen/v2/icons"
import {
  InsightsDrawerBody,
  OpportunitiesDrawerBody,
  OwnershipDrawerBody,
} from "@/components/mockups/scenario-single-screen/v2/review-drawers"
import {
  RailGroup,
  SettingRow,
} from "@/components/mockups/scenario-single-screen/v2/setting-rail"
import { SettingSheet } from "@/components/mockups/scenario-single-screen/v2/setting-sheet"
import {
  DATA_EXTRACTION,
  DEFAULT_LANGUAGE,
  DESTINATIONS,
  type Destination,
  INSIGHTS,
  type InsightTarget,
  KNOWLEDGE_BASES,
  LANGUAGE_LABELS,
  LANGUAGE_SHORT,
  type LanguageCode,
  OPPORTUNITIES,
  PER_LANGUAGE,
  RECORD_SINKS,
  SCENARIO,
  SUCCESS_CRITERIA,
  TEMPLATE_VARIABLES,
  TIMEZONE,
  TOOLS,
  type ToolSlug,
  UNRESOLVED_INSIGHTS,
} from "@/lib/mockups/scenario-single-screen-data"
import {
  IMPLICIT_VARIABLES,
  SECTIONED_PROMPTS,
  type SectionedPrompt,
} from "@/lib/mockups/scenario-single-screen-v2-data"
import { PromptBuilder } from "@/components/mockups/scenario-single-screen/v2/prompt-builder"
import { RawPromptDrawer } from "@/components/mockups/scenario-single-screen/v2/raw-prompt-drawer"

/** Every drawer this screen can open. One at a time, by design. */
type Setting =
  | "criteria"
  | "extraction"
  | "insights"
  | "knowledge"
  | "languages"
  | "opportunities"
  | "ownership"
  | "persona"
  | "recording"
  | "timezone"
  | "tools"
  | "variables"

/** Which drawer an insight's "open" button lands on. */
const INSIGHT_TARGETS: Record<InsightTarget, Setting | null> = {
  criteria: "criteria",
  extraction: "extraction",
  knowledge: "knowledge",
  /* The prompt is on the page, so there is nothing to open — closing the
     drawer already puts the reader in front of it. */
  prompt: null,
  tools: "tools",
}

export function ScenarioEditor({ isStaff }: { isStaff: boolean }) {
  const [openSetting, setOpenSetting] = React.useState<Setting | null>(null)
  const [dirty, setDirty] = React.useState(false)

  const [language, setLanguage] = React.useState<LanguageCode>(DEFAULT_LANGUAGE)
  const [defaultLanguage, setDefaultLanguage] =
    React.useState<LanguageCode>(DEFAULT_LANGUAGE)
  const [perLanguage, setPerLanguage] = React.useState(PER_LANGUAGE)
  const [timezone, setTimezone] = React.useState(TIMEZONE)
  const [bases, setBases] = React.useState(KNOWLEDGE_BASES)
  const [tools, setTools] = React.useState(TOOLS)
  const [criteria, setCriteria] = React.useState(SUCCESS_CRITERIA)
  const [variables, setVariables] = React.useState(TEMPLATE_VARIABLES)
  const [extractionOn, setExtractionOn] = React.useState(
    DATA_EXTRACTION.enabled,
  )
  const [destinations, setDestinations] = React.useState(DESTINATIONS)
  const [zohoRecording, setZohoRecording] = React.useState(
    RECORD_SINKS.zohoCallActivity,
  )
  const [dismissedInsights, setDismissedInsights] = React.useState<string[]>([])
  const [sectioned, setSectioned] = React.useState(SECTIONED_PROMPTS)
  const [rawOpen, setRawOpen] = React.useState(false)

  /** Every edit on this screen is the same kind of edit — one save bar. */
  const edit = <T,>(setter: (value: T) => void) => {
    return (value: T) => {
      setter(value)
      setDirty(true)
    }
  }

  const current =
    perLanguage.find((entry) => entry.language === language) ?? perLanguage[0]

  const updateCurrent = (patch: Partial<(typeof perLanguage)[number]>) => {
    setPerLanguage((entries) =>
      entries.map((entry) =>
        entry.language === language ? { ...entry, ...patch } : entry,
      ),
    )
    setDirty(true)
  }

  const currentSections =
    sectioned.find((entry) => entry.language === language) ?? sectioned[0]

  const updateSections = (next: SectionedPrompt) => {
    setSectioned((entries) =>
      entries.map((entry) => (entry.language === language ? next : entry)),
    )
    setDirty(true)
  }

  /* The prompt spends names the variables table does not declare — the agent's
     own name comes from the persona, not from a column. Both are offered. */
  const insertableVariables = [
    ...IMPLICIT_VARIABLES,
    ...variables.map((variable) => variable.name),
  ]

  const spokenLanguages = perLanguage.map((entry) => entry.language)
  const attachedBases = bases.filter((base) => base.attached)
  const enabledTools = tools.filter((tool) => tool.enabled)
  const enabledDestinations = destinations.filter(
    (destination) => destination.enabled,
  )
  const openInsights = UNRESOLVED_INSIGHTS - dismissedInsights.length

  const reset = () => {
    setPerLanguage(PER_LANGUAGE)
    setSectioned(SECTIONED_PROMPTS)
    setDefaultLanguage(DEFAULT_LANGUAGE)
    setTimezone(TIMEZONE)
    setBases(KNOWLEDGE_BASES)
    setTools(TOOLS)
    setCriteria(SUCCESS_CRITERIA)
    setVariables(TEMPLATE_VARIABLES)
    setExtractionOn(DATA_EXTRACTION.enabled)
    setDestinations(DESTINATIONS)
    setZohoRecording(RECORD_SINKS.zohoCallActivity)
    setDirty(false)
  }

  return (
    <div className="flex flex-1 flex-col p-3 lg:p-4">
      <div className="mx-auto flex w-full max-w-350 flex-col gap-6">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-2xl font-semibold">{SCENARIO.name}</h1>
              <Badge className="bg-success/10 text-success">Active</Badge>
            </div>
            {/* The four numbers the header carried before, as one line. They
                are context for the editing below, not a dashboard. */}
            <p className="text-sm text-muted-foreground">
              {SCENARIO.calls.toLocaleString()} calls · {SCENARIO.successRate}%
              met success criteria · Created {SCENARIO.createdAt} · Published{" "}
              {SCENARIO.lastPublished}
            </p>
          </div>

          <div className="flex shrink-0 items-center gap-2">
            <Button
              onClick={() => {
                setOpenSetting("insights")
              }}
              variant="outline"
            >
              <InsightsIcon />
              Insights
              <Badge variant="secondary">{openInsights}</Badge>
            </Button>
            <Button variant="outline">
              <TestCallIcon />
              Test
            </Button>
            <Button>
              <PublishIcon />
              Publish
            </Button>
          </div>
        </header>

        <div className="flex flex-col gap-6 lg:flex-row lg:items-start">
          {/* What the agent says. The only thing on this screen a person
              writes rather than picks, so it gets the width. */}
          <div className="flex min-w-0 flex-1 flex-col gap-4">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p className="text-sm text-muted-foreground">
                Writing the {LANGUAGE_LABELS[current.language]} version
                {current.language === defaultLanguage ? " — the default" : ""}
              </p>
              <ToggleGroup
                onValueChange={(next) => {
                  if (next) setLanguage(next as LanguageCode)
                }}
                size="sm"
                type="single"
                value={language}
                variant="outline"
              >
                {perLanguage.map((entry) => (
                  <ToggleGroupItem
                    aria-label={LANGUAGE_LABELS[entry.language]}
                    key={entry.language}
                    value={entry.language}
                  >
                    {LANGUAGE_SHORT[entry.language]}
                  </ToggleGroupItem>
                ))}
              </ToggleGroup>
            </div>

            <Card>
              <CardHeader>
                <CardTitle>First message</CardTitle>
                <CardDescription>
                  What the agent opens the call with. Leave it off to let the
                  caller speak first.
                </CardDescription>
                <CardAction>
                  <Switch
                    aria-label="First message"
                    checked={current.firstMessageEnabled}
                    onCheckedChange={(checked) => {
                      updateCurrent({ firstMessageEnabled: checked })
                    }}
                  />
                </CardAction>
              </CardHeader>
              <CardContent>
                <Input
                  aria-label="First message"
                  dir={
                    current.language === "ar" || current.language === "ur"
                      ? "rtl"
                      : "ltr"
                  }
                  disabled={!current.firstMessageEnabled}
                  onChange={(event) => {
                    updateCurrent({ firstMessage: event.target.value })
                  }}
                  value={current.firstMessage}
                />
              </CardContent>
            </Card>

            <PromptBuilder
              onChange={updateSections}
              onOpenRaw={() => {
                setRawOpen(true)
              }}
              onOpenVariables={() => {
                setOpenSetting("variables")
              }}
              prompt={currentSections}
              rtl={current.language === "ar" || current.language === "ur"}
              variables={insertableVariables}
            />
          </div>

          {/* Everything the scenario is set to, readable without opening a
              thing. The rail is the replacement for the Configuration tab. */}
          <aside className="flex w-full shrink-0 flex-col gap-4 lg:sticky lg:top-4 lg:w-96">
            <RailGroup title="How it speaks">
              <SettingRow
                icon={PersonaIcon}
                onOpen={() => {
                  setOpenSetting("persona")
                }}
                title="Persona"
                value={current.persona}
              />
              <SettingRow
                icon={LanguagesIcon}
                onOpen={() => {
                  setOpenSetting("languages")
                }}
                title="Languages"
                value={`${spokenLanguages
                  .map((code) => LANGUAGE_LABELS[code])
                  .join(", ")} · ${LANGUAGE_LABELS[defaultLanguage]} default`}
              />
              <SettingRow
                icon={TimezoneIcon}
                onOpen={() => {
                  setOpenSetting("timezone")
                }}
                title="Timezone"
                value={timezone}
              />
            </RailGroup>

            <RailGroup title="What it knows and can do">
              <SettingRow
                icon={KnowledgeIcon}
                onOpen={() => {
                  setOpenSetting("knowledge")
                }}
                title="Knowledge bases"
                value={
                  attachedBases.length === 0
                    ? "None attached"
                    : attachedBases.map((base) => base.name).join(", ")
                }
              />
              <SettingRow
                icon={ToolsIcon}
                onOpen={() => {
                  setOpenSetting("tools")
                }}
                title="Tools"
                value={
                  enabledTools.length === 0
                    ? "None enabled"
                    : enabledTools.map((tool) => tool.label).join(", ")
                }
              />
              <SettingRow
                icon={VariablesIcon}
                onOpen={() => {
                  setOpenSetting("variables")
                }}
                title="Template variables"
                value={`${variables.length} · ${
                  variables.filter((variable) => variable.required).length
                } required`}
              />
            </RailGroup>

            <RailGroup title="When the call ends">
              <SettingRow
                icon={CriteriaIcon}
                onOpen={() => {
                  setOpenSetting("criteria")
                }}
                title="Success criteria"
                value={`${criteria.length} criteria · ${
                  criteria.filter((criterion) => criterion.primary).length
                } primary`}
              />
              <SettingRow
                icon={ExtractionIcon}
                onOpen={() => {
                  setOpenSetting("extraction")
                }}
                title="Data extraction"
                value={
                  extractionOn
                    ? `${DATA_EXTRACTION.fields.length} fields → ${
                        enabledDestinations.length === 0
                          ? "nowhere yet"
                          : enabledDestinations
                              .map((destination) => destination.label)
                              .join(", ")
                      }`
                    : "Off"
                }
              />
              <SettingRow
                icon={RecordingIcon}
                onOpen={() => {
                  setOpenSetting("recording")
                }}
                title="Recording delivery"
                value={zohoRecording ? "Zoho call activity" : "Not delivered"}
              />
            </RailGroup>

            {isStaff ? (
              <RailGroup title="Sarj staff">
                <SettingRow
                  icon={OpportunitiesIcon}
                  onOpen={() => {
                    setOpenSetting("opportunities")
                  }}
                  title="Optimization opportunities"
                  value={`${OPPORTUNITIES.length} open`}
                />
                <SettingRow
                  icon={OwnershipIcon}
                  onOpen={() => {
                    setOpenSetting("ownership")
                  }}
                  title="Owning organization"
                  value="Sizzler KSA"
                />
              </RailGroup>
            ) : null}
          </aside>
        </div>
      </div>

      {/* One save bar for the page and every drawer on it, so there is a
          single answer to "is this live yet". */}
      {dirty ? (
        <div className="sticky bottom-4 z-sticky mx-auto mt-6 w-full max-w-350">
          <Card>
            <CardContent className="flex flex-wrap items-center justify-between gap-4">
              <div className="flex items-center gap-2">
                <span className="text-warning">
                  <UnsavedIcon />
                </span>
                <p className="text-sm font-medium">You have unsaved changes</p>
              </div>
              <div className="flex items-center gap-2">
                <Button onClick={reset} variant="outline">
                  Clear
                </Button>
                <Button
                  onClick={() => {
                    setDirty(false)
                  }}
                >
                  Save
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      ) : null}

      {/* --- the drawers ------------------------------------------------- */}

      <SettingSheet
        description="One voice per language. The persona also carries the turn timing and backchannel settings that language uses."
        onOpenChange={(open) => {
          setOpenSetting(open ? "persona" : null)
        }}
        open={openSetting === "persona"}
        title="Persona"
      >
        <PersonaDrawerBody
          onPersonaChange={(code, persona) => {
            setPerLanguage((entries) =>
              entries.map((entry) =>
                entry.language === code ? { ...entry, persona } : entry,
              ),
            )
            setDirty(true)
          }}
          perLanguage={perLanguage}
        />
      </SettingSheet>

      <SettingSheet
        description="Each language keeps its own prompt, first message and persona."
        onOpenChange={(open) => {
          setOpenSetting(open ? "languages" : null)
        }}
        open={openSetting === "languages" || openSetting === "timezone"}
        title="Languages and timezone"
      >
        <LanguagesDrawerBody
          defaultLanguage={defaultLanguage}
          onDefaultChange={edit(setDefaultLanguage)}
          onTimezoneChange={edit(setTimezone)}
          perLanguage={perLanguage}
          timezone={timezone}
        />
      </SettingSheet>

      <SettingSheet
        description="Attached bases are searched when the agent needs a fact it was not told."
        onOpenChange={(open) => {
          setOpenSetting(open ? "knowledge" : null)
        }}
        open={openSetting === "knowledge"}
        title="Knowledge bases"
      >
        <KnowledgeDrawerBody
          bases={bases}
          onToggle={(name) => {
            setBases((entries) =>
              entries.map((base) =>
                base.name === name
                  ? { ...base, attached: !base.attached }
                  : base,
              ),
            )
            setDirty(true)
          }}
          spokenLanguages={spokenLanguages}
        />
      </SettingSheet>

      <SettingSheet
        description="Actions the agent can take during a call, beyond talking."
        onOpenChange={(open) => {
          setOpenSetting(open ? "tools" : null)
        }}
        open={openSetting === "tools"}
        title="Tools"
      >
        <ToolsDrawerBody
          onToggle={(slug: ToolSlug) => {
            setTools((entries) =>
              entries.map((tool) =>
                tool.slug === slug ? { ...tool, enabled: !tool.enabled } : tool,
              ),
            )
            setDirty(true)
          }}
          tools={tools}
        />
      </SettingSheet>

      <SettingSheet
        description="What a call has to achieve to be scored as successful."
        onOpenChange={(open) => {
          setOpenSetting(open ? "criteria" : null)
        }}
        open={openSetting === "criteria"}
        title="Success criteria"
      >
        <CriteriaDrawerBody
          criteria={criteria}
          onCriteriaChange={edit(setCriteria)}
        />
      </SettingSheet>

      <SettingSheet
        description="Placeholders the prompt and first message fill in when a call starts."
        onOpenChange={(open) => {
          setOpenSetting(open ? "variables" : null)
        }}
        open={openSetting === "variables"}
        title="Template variables"
      >
        <VariablesDrawerBody
          onVariablesChange={edit(setVariables)}
          variables={variables}
        />
      </SettingSheet>

      <SettingSheet
        description="Fields read out of the transcript when the call ends, and where they go."
        onOpenChange={(open) => {
          setOpenSetting(open ? "extraction" : null)
        }}
        open={openSetting === "extraction"}
        title="Data extraction"
      >
        <ExtractionDrawerBody
          destinations={destinations}
          enabled={extractionOn}
          fields={DATA_EXTRACTION.fields}
          onDestinationToggle={(type: Destination["type"]) => {
            setDestinations((entries) =>
              entries.map((destination) =>
                destination.type === type
                  ? { ...destination, enabled: !destination.enabled }
                  : destination,
              ),
            )
            setDirty(true)
          }}
          onEnabledChange={edit(setExtractionOn)}
        />
      </SettingSheet>

      <SettingSheet
        description="Where the call recording is sent once the call ends."
        onOpenChange={(open) => {
          setOpenSetting(open ? "recording" : null)
        }}
        open={openSetting === "recording"}
        title="Recording delivery"
      >
        <RecordingDrawerBody
          onZohoChange={edit(setZohoRecording)}
          zohoCallActivity={zohoRecording}
        />
      </SettingSheet>

      <SettingSheet
        description="What the last 90 days of calls say about this scenario."
        onOpenChange={(open) => {
          setOpenSetting(open ? "insights" : null)
        }}
        open={openSetting === "insights"}
        title="Insights"
      >
        <InsightsDrawerBody
          dismissed={dismissedInsights}
          insights={INSIGHTS}
          onDismiss={(title) => {
            setDismissedInsights((titles) => [...titles, title])
          }}
          onOpenTarget={(target) => {
            setOpenSetting(INSIGHT_TARGETS[target])
          }}
        />
      </SettingSheet>

      <SettingSheet
        description="Cost and quality wins Sarj staff can act on for this scenario."
        onOpenChange={(open) => {
          setOpenSetting(open ? "opportunities" : null)
        }}
        open={openSetting === "opportunities"}
        title="Optimization opportunities"
      >
        <OpportunitiesDrawerBody opportunities={OPPORTUNITIES} />
      </SettingSheet>

      <SettingSheet
        description="Move this scenario to another organization."
        onOpenChange={(open) => {
          setOpenSetting(open ? "ownership" : null)
        }}
        open={openSetting === "ownership"}
        title="Owning organization"
      >
        <OwnershipDrawerBody attachedBases={attachedBases.length} />
      </SettingSheet>

      <RawPromptDrawer
        onOpenChange={setRawOpen}
        open={rawOpen}
        prompt={currentSections}
        rtl={current.language === "ar" || current.language === "ur"}
      />
    </div>
  )
}

